                block_set = set(grid[(i // 3) * 3 + x][(j // 3) * 3 + y] for x in range(3) for y in range(3))
                if len(row_set) > 1 and len(col_set) > 1 and len(block_set) > 1:
                    unique_cells.append((i, j))
        return unique_cells

    def replace_unique_with_duplicate(i, j):
        current_value = grid[i][j]
        for new_value in range(1, 10):
            if str(new_value) != current_value:
                grid[i] = grid[i][:j] + str(new_value) + grid[i][j+1:]
                break

    unique_cells = find_unique_cells()
    for cell in unique_cells[:9]:
        replace_unique_with_duplicate(*cell)

    return grid

def solve(t, grids):
    results = []
    for _ in range(t):
        grid = [list(input().strip()) for _ in range(9)]
        anti_sudoku_grid = make_anti_sudoku(grid)
        results.append('\n'.join(''.join(row) for row in anti_sudoku_grid))
    return '\n'.join(results)

